// Timeline (`timeline.tenshu.app`) — a Tenshu app on its own origin (ADR 0020), on the shared app
// preset (`@tenshu/app-kit`, web-app-suite.md F3): Vite + Vitest + Tailwind, the dev server's
// `fs.allow` and the served `manifest.webmanifest`. Generated by scripts/new-web-app.sh.
//
// ⚠ Imported by its file path, not `@tenshu/app-kit/vite`: Node loads this config and refuses to
// strip types from a `.ts` it resolved through `node_modules`.
import { mergeConfig } from 'vite'
import { tenshuAppConfig } from '../app-kit/src/vite.ts'
// Glyphs for the trip and place maps, served from this origin (how-to new-web-app.md §2b; no font CDN).
import { tenshuMapGlyphs } from '../map-kit/src/vite.ts'

// ⚠ No `chunkSizeWarningLimit` override: this bundle must NOT contain the Kotlin runtime, so Vite's
// default 500 kB warning is the tripwire for a stray SDK value import — on the ENTRY chunk
// (`assets/index-*.js`). The lazy `MapView-*.js` chunk (MapLibre, ~1 MB) trips it by design and
// loads only with a map (`src/mapSplit.test.ts`); raising the limit for it would blind the tripwire.
export default mergeConfig(
  tenshuAppConfig({
    // The apex registry entry (`web/apex/src/apps/registry/apps/timeline.ts`) names the same port.
    port: 5177,
    manifest: {
      id: 'timeline',
      name: 'Timeline',
      description: 'Where you have been, end-to-end encrypted.',
      // docs/web/architecture.md §6. Display/declaration data; the apex allowlist is the enforcement.
      semanticPermissions: [
        {
          id: 'tenshu/timeline/service',
          humanDescription: 'Read your timeline; rename, label, merge and separate places; save suggested trips',
          scope: ['/'],
        },
      ],
    },
  }),
  { plugins: [tenshuMapGlyphs()] },
)
